import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    private static Map<Long, Long> cache = new HashMap<>();

    public static long compute(long n) {
        if (cache.containsKey(n)) {
            return cache.get(n);
        }
        if (n <= 11) {
            long result = Math.min(n, 2 + (11 - n));
            cache.put(n, result);
            return result;
        }
        long x = 1;
        int c = 1;
        while (x <= n) {
            x = x * 10 + 1;
            c++;
        }
        long base = x / 10;
        long quotient = n / base;
        long remainder = n % base;
        long res = Math.min(compute(x - n) + c, quotient * (c - 1) + compute(remainder));
        cache.put(n, res);
        return res;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long s = scanner.nextLong();
        System.out.println(compute(s));
        scanner.close();
    }
}
